public class WidgetTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Widget.reset();
        check("count after reset", 0, Widget.createdCount());

        new Widget();
        new Widget();
        new Widget();
        check("count after creating 3 widgets", 3, Widget.createdCount());

        new Widget();
        check("count after one more widget", 4, Widget.createdCount());

        Widget.reset();
        check("count after second reset", 0, Widget.createdCount());

        new Widget();
        check("count restarts after reset", 1, Widget.createdCount());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

